metrics.workdir_dsl:
workspace "Home Energy Management Platform" "C4 model of the home energy management platform" {

    configuration {
        scope "SoftwareSystem"
    }

    model {
        homeowner = person "Homeowner" "A homeowner who manages the household's energy use and costs"

        energyManager = softwareSystem "Energy Manager" "A home energy management platform for managing household energy use and costs. Owned and operated by our company" {
            dashboard = container "Dashboard Web App" "Where homeowners see consumption and costs" "Web application"
            schedulingService = container "Scheduling Service" "Plans charging and heating" "Service"
            ratesLibrary = container "Rates Library" "Computes energy prices from tariff and time of day" "Shared library"
            database = container "Database" "Stores meter readings and schedules" "Database"

            !docs "Overview" "The Energy Manager is a home energy management platform for managing household energy use and costs."
            !decisions "Architecture" "The platform consists of a dashboard web app and a scheduling service, both of which embed a shared rates library."
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings. Operated by a different organization"

        homeowner -> energyManager "Manages household energy use and costs" "Web browser"
        homeowner -> dashboard "Sees consumption and costs" "Web browser"
        dashboard -> ratesLibrary "Embeds" "Embedded"
        schedulingService -> ratesLibrary "Embeds" "Embedded"
        schedulingService -> smartMeterProvider "Fetches live meter readings" "HTTPS"
        schedulingService -> database "Stores meter readings and schedules" "SQL"
    }

    views {
        systemContext energyManager "SystemContext" "The system context diagram for the Energy Manager" {
            include *
            autoLayout
        }

        container energyManager "Containers" "The container diagram for the Energy Manager" {
            include *
            autoLayout
        }
    }
}
